const small = ['a','an','the','and','or','but','for','nor','on','in','at','to','by','of','with','as','from'];
return text.split(' ').map((word, i, arr) => {
  const m = word.match(/^(\W*)(.*?)(\W*)$/);
  const lead = m[1], core = m[2], trail = m[3];
  const capped = core.charAt(0).toUpperCase() + core.slice(1).toLowerCase();
  const isSmall = small.includes(core.toLowerCase());
  const out = (i === 0 || i === arr.length - 1 || !isSmall) ? capped : core.toLowerCase();
  return lead + out + trail;
}).join(' ');

let up = true;
return text.replace(/[A-Za-z]/g, (c) => {
  const r = up ? c.toUpperCase() : c.toLowerCase();
  up = !up;
  return r;
});

if (/^>\s*\[!/.test(text)) return text;
const lines = text.split('\n');
const body = lines.map(l => l.trim() === '' ? l : (l.startsWith('>') ? l : '> ' + l)).join('\n');
return '> [!note]\n' + body;

let n = 0;
return text
  .split('\n')
  .map(l => {
    if (/^\s*[a-zA-Z0-9][.)]\s+/.test(l)) { n++; return l.replace(/^\s*[a-zA-Z0-9][.)]\s+/, n + '. '); }
    return l;
  })
  .filter(l => l.trim() !== '')
  .join('\n');

const lines = text.split('\n').filter(l => l.includes('|') && !/^\s*\|?[-: |]+\|?\s*$/.test(l));
const out = [];
for (const line of lines) {
  const cells = line.split('|').map(c => c.trim()).filter(c => c !== '');
  if (!cells.length) continue;
  out.push('- ' + cells[0]);
  for (let i = 1; i < cells.length; i++) out.push('  - ' + cells[i]);
}
return out.join('\n');

const lines = text.split('\n').filter(l => l.includes('|') && !/^\s*\|?[-: |]+\|?\s*$/.test(l));
if (!lines.length) return text;
const header = lines[0].split('|').map(c => c.trim()).filter(c => c !== '');
const out = [];
for (let r = 1; r < lines.length; r++) {
  const cells = lines[r].split('|').map(c => c.trim()).filter(c => c !== '');
  if (!cells.length) continue;
  out.push('- ' + cells[0]);
  for (let i = 1; i < cells.length; i++) {
    const h = header[i] || '';
    out.push('  - ' + (h ? h + ': ' : '') + cells[i]);
  }
}
return out.join('\n');

return text.split('\n').sort((a, b) => {
  const ca = a.replace(/^[-*]\s*\[[ xX]\]\s*/, '').toLowerCase();
  const cb = b.replace(/^[-*]\s*\[[ xX]\]\s*/, '').toLowerCase();
  return ca.localeCompare(cb);
}).join('\n');

return text.replace(/\[\[([^\]|]+)(?:\|([^\]]+))?\]\]/g, (m, t, alias) => {
  const label = alias || t;
  return '[' + label + '](' + t + '.md)';
});
